import numpy as np, json
cp=[((710,2145),(35.00,29.53)),((570,1648),(34.45,31.52)),((1035,1148),(36.29,33.51)),((1528,885),(38.27,34.56)),((1252,471),(37.16,36.20)),((685,296),(34.89,36.92)),((1710,528),(39.01,35.95)),((1592,148),(38.53,37.51)),((945,1983),(35.73,30.19)),((1162,143),(36.93,37.58)),((922,918),(35.84,34.43))]
P=np.array([[x,y,1,x*x,x*y,y*y] for (x,y),_ in cp]); L=np.array([l for _,l in cp])
co,*_=np.linalg.lstsq(P,L,rcond=None)
res=P@co-L; print('max resid deg',np.abs(res).max().round(3))
f=lambda x,y: tuple(np.array([x,y,1,x*x,x*y,y*y])@co)
pts=[(475,450),(460,450),(400,415),(365,400),(390,350),(450,300),(500,290),(560,250),(640,215),(720,165),(780,140),(860,115),(960,85),(1060,60),(1180,45),(1300,35),(1365,35),(1400,95),(1415,150),(1430,200),(1435,250),(1460,280),(1475,350),(1515,365),(1535,390),(1515,410),(1515,460),(1490,480),(1495,515),(1540,540),(1600,555),(1640,545),(1715,545),(1740,595),(1820,620),(1810,700),(1790,780),(1740,880),(1700,900),(1600,1040),(1550,1130),(1490,1230),(1470,1270),(1440,1350),(1400,1470),(1370,1540),(1320,1640),(1280,1700),(1220,1790),(1160,1860),(1100,1930),(1030,2000),(950,2050),(890,2100),(810,2130),(700,2155),(685,2150),(600,2050),(540,1950),(500,1850),(460,1730),(380,1730),(600,1300),(600,480)]
ring=[f(*p) for p in pts]; ring.append(ring[0])
json.dump({'type':'Polygon','coordinates':[[list(map(float,p)) for p in ring]]},open('sham_trace.json','w'))
for p,q in zip(pts[::8],ring[::8]): print(p,[round(v,2) for v in q])
